  function getConversationTargets(){return [...state.nativeConversations.map(c=>({kind:'native',targetId:c.id,name:nativeTitle(c),unread:Number(c.unreadCount)||0,isDirect:c.kind==='dm'})),...state.secureRooms.map(room=>({kind:'matrix',targetId:room.id,name:room.name,unread:Number(room.unreadCount)||0,isDirect:room.isDirect===true})),...state.channels.map(item=>({kind:'channel',targetId:item.id,name:item.name,communityId:state.communityId,unread:Number(item.unread_count)||0}))];}
