      if(!current()||nativeKey()!==key)return;mergeNative([...(result.messages||[]),...changes]);state.nativeCursor=Math.max(after,...nativeRows().map(m=>Number(m.seq)||0));if(direct)state.nativeChangeCursor=Number(result.changeCursor)||state.nativeChangeCursor;state.nativeError='';state.nativeConnection='Last checked '+new Date().toLocaleTimeString()+' · updates every 5 seconds';paintNative();
