  async function markNativeRead(){const seq=Math.max(0,...nativeRows().map(m=>Number(m.seq)||0)),current=guard();if(!nativeKey()||!seq||document.hidden)return;const payload={seq,changeSeq:state.nativeChangeCursor};await request(state.nativeId?nativePath()+'/read':'/api/live/read',state.nativeId?payload:{...payload,channelId:state.channelId});if(current()&&state.nativeId){const c=state.nativeConversations.find(c=>c.id===state.nativeId);if(c&&seq>=Number(c.lastSeq||0))c.unreadCount=0;}return current();}
