    if(action==='reaction'){const current=guard(),emoji=button.dataset.emoji,active=!message.reactions?.find(r=>r.emoji===emoji)?.mine;if(button)button.disabled=true;try{const result=await request((state.nativeId?'/api/messages/messages/':'/api/live/messages/')+encodeURIComponent(id)+'/'+(state.nativeId?'react':'reaction'),{emoji,active,acknowledgeStandard:true});if(!current()||nativeKey()!==key)return;mergeNative([result.message]);if(ticket===state.dialogGeneration)closeDialog();paintNative();}finally{if(button?.isConnected)button.disabled=false;}}
