  function createDialog(){showDialog('Create a server','A new server starts with only you. Creating it also creates its first text channel.',`<form data-home-form="create" class="vh-form"><label class="vh-field">Server name<input name="name" maxlength="64" required autofocus></label><label class="vh-field">Description <span>Optional</span><textarea name="description" maxlength="240" rows="3"></textarea></label><label class="vh-field">Icon text <span>Up to 8 characters</span><input name="icon" maxlength="8" value="WL"></label>${formError}<button class="vh-primary" type="submit">Create server</button></form>`);}
