  function dataDialog(){showDialog('Your data','Previous device-local archives are never uploaded into your account automatically.',`<div class="vh-note"><b>Previous local archive</b><p>Export the untouched records from this browser for review. Existing fixtures and genuine contributions remain in the original archive; this action does not turn samples into account conversations.</p><button class="vh-secondary" data-home="review-local">Review previous archive</button><button class="vh-secondary" data-home="export-local">Export previous local archive</button></div><p>Shared account data and previous unencrypted server history are preserved. Full account export is not available in this release. You can delete your account after transferring any servers you own.</p><a class="vh-secondary" href="downloads/voidline-source.zip" download>Download source</a><button class="vh-danger" data-home="delete-account">Delete account</button>`);}
  function exportLocal(){try{const keys=[];for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key==='voidline.local.v1'||key==='voidline.archive.v3.base'||key?.startsWith('voidline.archive.v3.op.'))keys.push(key);}if(!keys.length)return announce('No previous local archive was found in this browser.');const records=Object.fromEntries(keys.map(key=>[key,localStorage.getItem(key)]));const data=JSON.stringify({format:'voidline-untouched-browser-records',version:1,records},null,2);const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='voidline-previous-local-archive.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);announce('Previous local records exported. Nothing was imported or uploaded.');}catch(_){announce('This browser could not read its previous archive. No records were changed.');}}
  async function saved(){const current=guard();const ticket=showDialog('Saved Messages.','A personal utility outside your conversation list.',`<div id="home-saved" role="status">Loading Saved…</div>${formError}`);try{const data=await request('/api/live/saved?limit=30&offset=0');if(!current()||ticket!==state.dialogGeneration)return;const n=$('home-saved');if(n)n.innerHTML=data.total?`<p class="vh-note">These ${Number(data.total)} saved records predate encrypted messaging.</p>`+(data.messages||[]).map(m=>`<article class="vh-list-row"><div><b>${esc(m.author_name||'Unavailable original')}</b><p>${m.unavailable?'The original is unavailable.':esc(m.text||'Deleted message')}</p></div></article>`).join(''):'<div class="vh-history-empty"><h3>Nothing saved yet.</h3><p>Your account starts with an empty personal space.</p></div>';}catch(error){if(current()&&ticket===state.dialogGeneration)errorNode(error);}}
