    const actions=!unavailable?`<div class="vh-message-actions"><button data-secure-action="reply" data-event="${esc(message.id)}" ${deleted?'disabled':''}>${icon('reply')}<span>Reply</span></button><button data-secure-action="thread" data-event="${esc(message.id)}">${icon('thread')}<span>Thread</span></button>${!deleted?`<button data-secure-action="react" data-event="${esc(message.id)}">${icon('smile')}<span>React</span></button>`:''}<button data-secure-action="more" data-event="${esc(message.id)}" aria-label="More actions for this message">${icon('more')}</button></div>`:'';
