    try{const receipt=await messenger.sendAttachment(selected.roomId,selected.file,{clientId:selected.clientId,signal:abort.signal,voice:selected.voice,durationMs:selected.durationMs,replyToId:selected.replyToId,threadRootId:selected.threadRootId,onProgress(progress){if(!current()||ticket!==state.dialogGeneration)return;const loaded=typeof progress==='number'?progress:Number(progress.loaded)||0,total=Number(progress.total)||0,value=typeof progress==='number'?Math.min(100,progress<=1?progress*100:progress):total?loaded/total*100:0;const node=$('home-upload-progress');if(node)node.value=value;const label=$('home-upload-state');if(label)label.textContent=total||typeof progress==='number'?`Uploading encrypted file · ${Math.round(value)}%`:'Uploading encrypted file…';}});
      if(!current()||messenger!==state.secure||abort.signal.aborted)return;if(reviewedAttachment===selected)reviewedAttachment=null;if(ticket===state.dialogGeneration)closeDialog();const draft=secureDraft();if(draft&&draft.replyToId===selected.replyToId){draft.replyToId=null;persistSecureDraft();updateComposerContext();}await refreshSecureMessages();announce(receipt?.storageWarning||'Encrypted attachment saved by the messaging service.');
    }catch(error){if(current()&&ticket===state.dialogGeneration){errorNode(error);const label=$('home-upload-state');if(label)label.textContent='Upload not confirmed. Retry keeps the same message ID.';}}
